actions.script:
const addId = (idList, id) => { if (id && !idList.includes(id)) idList.push(id) }
for (const returnItem of returnItemList) {
    if (isVendorOrgInternal) {
        addId(salesOrderIdSet, returnItem.orderId)
        addId(replacementOrderIdSet, returnItem.replacementOrderId)
    } else {
        addId(purchaseOrderIdSet, returnItem.orderId)
    }
    addId(refundPaymentIdSet, returnItem.refundPaymentId)
}
salesOrderIdSet.sort()
replacementOrderIdSet.sort()
purchaseOrderIdSet.sort()
refundPaymentIdSet.sort()

const shipmentIdList = isVendorOrgInternal ? receivingShipmentIdSet : shippingShipmentIdSet
for (const sis of shipmentItemSourceList) {
    if (!shipmentIdList.includes(sis.shipmentId)) shipmentIdList.push(sis.shipmentId)
}
shipmentIdList.sort()

iterate.script:
const summaryKey = receipt.returnId + ':' + receipt.returnItemSeqId
const summary = receiptSummaryMap[summaryKey] ??= {returnId:receipt.returnId, returnItemSeqId:receipt.returnItemSeqId, quantityAccepted:toDecimal(0)}
summary.quantityAccepted = summary.quantityAccepted.add(receipt.quantityAccepted)

service-call.in-map:
{returnId:returnId, returnItemSeqId:returnItemSeqId, receivedQuantity:receivedQuantity,
                        returnQuantity:(hasResponse ? returnItem.returnQuantity : receivedQuantity),
                        statusId:(allReceived || !hasResponse ? 'ReturnReceived' : returnItem.statusId)}
